const rows = $input.all().map((item) => item.json || {});
const triggerInput = $('Execute Workflow Trigger').first().json || {};
const normalizedRows = rows.map((row) => ({
  week_start: row.week_start || null,
  created_at: row.created_at || null,
  comment_text: typeof row.comment_text === 'string' ? row.comment_text.trim() : '',
  avg_mood: row.avg_mood ?? null,
  avg_pace: row.avg_pace ?? null,
  avg_fairness: row.avg_fairness ?? null,
})).filter((row) => row.comment_text.length > 0);
const sourceWindow = rows[0]?.source_window ?? { weeks: Number(triggerInput.weeks || 2), n: 0, class_id: triggerInput.class_id || null };
const weekStart = rows[0]?.week_start ?? null;
const contributingStudentsCount = Number(rows[0]?.contributing_students_count ?? sourceWindow.n ?? 0);
return {
  json: {
    class_id: triggerInput.class_id || null,
    weeks: Number(triggerInput.weeks || 2),
    limit: Number(triggerInput.limit || 12),
    status: normalizedRows.length > 0 ? 'ready' : 'no_safe_batch',
    reason: normalizedRows.length > 0 ? null : 'no_safe_batch',
    batch_size: normalizedRows.length,
    week_start: weekStart,
    source_window: sourceWindow,
    contributing_students_count: contributingStudentsCount,
    rows: normalizedRows,
  }
};
